            'note_de_credit' => [
                'name' => 'Gutschrift',
                'alternate' => 'Storno-/Korrekturrechnung',
                'description' => 'Dokument, das eine bereits ausgestellte Rechnung ganz oder teilweise storniert oder mindert (Fehler, Rückgabe, Rabatt, Annullierung). Es verweist auf die ursprüngliche Rechnung, trägt eine eigene fortlaufende Nummer und wendet dieselbe MwSt wie die korrigierte Rechnung an.',
            ],
            'saf_t' => [
                'name' => 'SAF-T',
                'alternate' => 'Standard Audit File for Tax',
                'description' => 'Internationaler (OECD-)Standard für eine standardisierte Steuerprüfdatei, die Prüfungen erleichtert, indem Buchhaltungsdaten in einem gemeinsamen XML-Format exportiert werden. In Luxemburg ist das FAIA die von der AED geforderte Ausprägung.',
            ],
            'ubl' => [
                'name' => 'UBL',
                'alternate' => 'Universal Business Language',
                'description' => 'Offener XML-Standard (OASIS), der elektronische Geschäftsdokumente definiert (Rechnung, Gutschrift, Bestellung). Das in Europa für die E-Rechnung genutzte Peppol-BIS-Format basiert auf UBL 2.1.',
            ],
            'zugferd' => [
                'name' => 'ZUGFeRD',
                'alternate' => 'Hybride PDF/XML-Rechnung (Deutschland)',
                'description' => 'Deutsches hybrides E-Rechnungsformat, das ein lesbares PDF/A mit eingebetteten strukturierten XML-Daten kombiniert. Es beruht auf derselben Norm (EN 16931) wie das deutsch-französische Factur-X und ist damit weitgehend interoperabel.',
            ],
            'aed' => [
                'name' => 'AED',
                'alternate' => 'Verwaltung fuer Eintragung, Domaenen und Mehrwertsteuer',
                'description' => 'Luxemburgische Steuerverwaltung, zustaendig fuer die Mehrwertsteuer, die Eintragung von Urkunden und Erbschaftssteuern. Sie fuehrt Steuerpruefungen durch und ist die Empfaengerin der FAIA-Pruefdatei.',
            ],
            'autoliquidation' => [
                'name' => 'Reverse-Charge',
                'alternate' => 'Steuerschuldumkehr bei innergemeinschaftlichem B2B',
                'description' => 'Mechanismus, bei dem für Dienstleistungen zwischen Steuerpflichtigen in zwei EU-Mitgliedstaaten die MwSt nicht vom Leistungserbringer berechnet, sondern vom Kunden in seinem Land geschuldet wird. Die Rechnung trägt den Hinweis „Autoliquidation". Rechtsgrundlage: Artikel 17 LIVA (Ort der Leistung) und Artikel 196 der Richtlinie 2006/112/EG (Steuerschuldner).',
            ],
            'franchise_tva' => [
                'name' => 'MwSt-Befreiung (Kleinunternehmer)',
                'alternate' => 'Franchise-Regime für Kleinunternehmen',
                'description' => 'Regime für Steuerpflichtige mit einem Jahresumsatz unter 50 000 EUR netto (Schwelle seit 2025, mit einer Überschreitungstoleranz von 10 %). Unter dieser Regelung wird keine MwSt berechnet und keine Vorsteuer abgezogen. Ein Befreiungshinweis muss auf jeder Rechnung erscheinen (Regelung nach Artikel 57 ff. LIVA).',
            ],
            'numerotation_sequentielle' => [
                'name' => 'Fortlaufende Nummerierung',
                'alternate' => 'Verpflichtende lückenlose Rechnungsnummerierung',
                'description' => 'Verpflichtung, jeder Rechnung eine eindeutige, fortlaufende und lückenlose Nummer in einer ununterbrochenen chronologischen Reihe zu vergeben. Lücken oder Doppelnummern können zu einer Steuernachzahlung wegen vermuteter nicht erklärter Einnahmen führen. Rechtsgrundlage: Artikel 63 LIVA.',
            ],
            'ccss' => [
                'name' => 'CCSS',
                'alternate' => 'Gemeinsames Zentrum fuer soziale Sicherheit Luxemburg',
                'description' => 'Luxemburgische Stelle fuer die Verwaltung der Sozialversicherungsanmeldungen von Arbeitnehmern und Selbststaendigen. Jeder Einzelunternehmer meldet sich bei Gruendung beim CCSS an und meldet seine Einkuenfte zur Beitragsberechnung.',
            ],
            'factur_x' => [
                'name' => 'Factur-X',
                'alternate' => 'Hybrides Format PDF/A-3 + XML CII',
                'description' => 'Europaeische Norm fuer elektronische Rechnungen, die ein fuer Menschen lesbares PDF/A-3 mit einer eingebetteten XML-Datei (UN/CEFACT Cross Industry Invoice) kombiniert, lesbar von Buchhaltungssoftware. Eine einzige Rechnung, lesbar fuer beide Seiten.',
            ],
            // FAIA Export
    'faia' => [
                'name' => 'FAIA',
                'alternate' => 'Standardisierte Pruefdatei der AED',
                'description' => 'Strukturierte XML-Datei nach dem OECD-SAF-T-Standard, in der Version 2.01 von der AED veroeffentlicht, die alle Buchhaltungsdaten eines Unternehmens ueber einen bestimmten Zeitraum buendelt. Die AED kann sie bei einer Steuerpruefung verlangen; sie ist seit 2020 zentraler Bestandteil jeder MwSt-Pruefung.',
            ],
            'liva' => [
                'name' => 'LIVA',
                'alternate' => 'Luxemburgisches Mehrwertsteuergesetz',
                'description' => 'Gesetz vom 12. Februar 1979 in der geaenderten Fassung, das die MwSt in Luxemburg regelt: Steuerpflicht, Saetze, Pflichtangaben auf Rechnungen, Reverse-Charge, Befreiungen. Die meistzitierten Artikel sind 21 (Reverse-Charge), 56 ter (Befreiung) und 61 (Nummerierung).',
            ],
            'oss' => [
                'name' => 'OSS',
                'alternate' => 'One Stop Shop - EU-MwSt-Einheitsschalter',
                'description' => 'EU-Regime seit 1. Juli 2021, das Unternehmen erlaubt, die in mehreren Mitgliedstaaten geschuldete MwSt ueber einen einzigen Schalter anzumelden und zu zahlen, sobald die grenzueberschreitenden B2C-Verkaeufe 10 000 EUR pro Jahr ueberschreiten.',
            ],
            'pdf_a' => [
                'name' => 'PDF/A',
                'alternate' => 'Langzeitarchivformat - ISO 19005',
                'description' => 'Standardisierte PDF-Variante fuer die langfristige Archivierung: eingebettete Schriftarten, keine Skripte, keine externen Links. Es ist das von Artikel 16 des luxemburgischen Handelsgesetzbuchs vorgeschriebene Format fuer die 10-jaehrige Aufbewahrung von Rechnungen.',
            ],
            'peppol' => [
                'name' => 'Peppol',
                'alternate' => 'Pan-European Public Procurement OnLine',
                'description' => 'Internationales standardisiertes Netzwerk fuer den elektronischen Rechnungsaustausch (UBL oder CII) zwischen Unternehmen und oeffentlichen Verwaltungen. In Luxemburg seit 2023 verpflichtend fuer B2G-Rechnungen. Ein luxemburgischer Gesetzentwurf vom Juli 2026 sieht die Ausweitung auf das inländische B2B ab 2028 vor, die ViDA-Richtlinie auf das innergemeinschaftliche B2B ab dem 1. Juli 2030.',
            ],
            'rcs' => [
                'name' => 'RCS',
                'alternate' => 'Luxemburger Handels- und Gesellschaftsregister',
                'description' => 'Oeffentliches luxemburgisches Register zur Eintragung von Handelsunternehmen und Gesellschaften. Die RCS-Nummer (Praefix B gefolgt von Ziffern) ist eine Pflichtangabe auf luxemburgischen Rechnungen eingetragener Unternehmen.',
            ],
            'vida' => [
                'name' => 'ViDA',
                'alternate' => 'VAT in the Digital Age - europaeische MwSt-Reform',
                'description' => 'EU-Gesetzespaket vom Maerz 2025, das die MwSt in der EU modernisiert: schrittweise Pflicht zur strukturierten elektronischen Rechnungsstellung fuer innergemeinschaftliche B2B-Geschaefte, Echtzeit-Meldesystem (Digital Reporting) und Harmonisierung der Plattformwirtschaft. Schrittweise Umsetzung bis 2030.',
            ],
            'vies' => [
                'name' => 'VIES',
                'alternate' => 'VAT Information Exchange System',
                'description' => 'Von der Europaeischen Kommission verwaltetes System zur Echtzeit-Ueberpruefung einer innergemeinschaftlichen MwSt-Nummer. Vor jeder Reverse-Charge-B2B-Rechnung (Art. 196 der Richtlinie 2006/112/EG) muss die MwSt-Nummer des Kunden ueber VIES geprueft werden, sonst kann der Vorgang als in Luxemburg steuerpflichtig umqualifiziert werden.',
            ],
