    'legal_privacy_s10_title' => '10. Änderungen dieser Erklärung',
    'legal_privacy_s10_p1' => 'Wir können diese Datenschutzerklärung ändern. Bei wesentlichen Änderungen informieren wir Sie per E-Mail oder über eine Benachrichtigung im Dienst. Das Datum der letzten Aktualisierung steht oben in diesem Dokument.',
