    'legal_terms_s1_title' => '1. Gegenstand',
    'legal_terms_s1_p1' => 'Die vorliegenden Allgemeinen Geschäftsbedingungen (nachfolgend "AGB") regeln die Bedingungen, unter denen Alexandre Beaudier, Betreiber des Dienstes faktur.lu (nachfolgend "der Anbieter"), den Nutzern (nachfolgend "der Nutzer" oder "der Kunde") einen Online-Rechnungsdienst zur Verfügung stellt.',
    'legal_terms_s1_p2' => 'Die Registrierung und die Nutzung des Dienstes setzen die vollumfängliche Annahme dieser AGB voraus.',

    'legal_terms_s2_title' => '2. Begriffsbestimmungen',
    'legal_terms_s2_li1_label' => 'Dienst:',
    'legal_terms_s2_li1_text' => 'Die Webanwendung faktur.lu zur Erstellung und Verwaltung von Rechnungen, Angeboten, Gutschriften und Zeiterfassung.',
    'legal_terms_s2_li2_label' => 'Nutzer / Kunde:',
    'legal_terms_s2_li2_text' => 'Jede natürliche oder juristische Person, die ein Konto auf faktur.lu erstellt hat.',
    'legal_terms_s2_li3_label' => 'Konto:',
    'legal_terms_s2_li3_text' => 'Der persönliche Bereich des Nutzers, der über seine Zugangsdaten zugänglich ist.',
    'legal_terms_s2_li4_label' => 'Abonnement:',
    'legal_terms_s2_li4_text' => 'Kostenpflichtiges Paket, das Zugang zu erweiterten Funktionen des Dienstes gewährt.',
    'legal_terms_s2_li5_label' => 'Inhalte:',
    'legal_terms_s2_li5_text' => 'Die vom Nutzer eingegebenen Daten (Rechnungen, Kunden usw.).',

    'legal_terms_s3_title' => '3. Zugang zum Dienst',
    'legal_terms_s3_1_title' => '3.1 Registrierung',
    'legal_terms_s3_1_p' => 'Der Zugang zum Dienst erfordert die Erstellung eines Kontos. Der Nutzer muss korrekte und vollständige Angaben machen, insbesondere eine gültige E-Mail-Adresse.',
    'legal_terms_s3_2_title' => '3.2 Zulassungsvoraussetzungen',
    'legal_terms_s3_2_p' => 'Der Dienst richtet sich an Gewerbetreibende (Unternehmen, Selbstständige, Freiberufler). Der Nutzer erklärt:',
    'legal_terms_s3_2_li1' => 'volljährig und geschäftsfähig zu sein',
    'legal_terms_s3_2_li2' => 'im Rahmen seiner beruflichen Tätigkeit zu handeln',
    'legal_terms_s3_2_li3' => 'über die zur Nutzung des Dienstes erforderlichen Berechtigungen zu verfügen',
    'legal_terms_s3_3_title' => '3.3 Kontosicherheit',
    'legal_terms_s3_3_p' => 'Der Nutzer ist für die Vertraulichkeit seiner Zugangsdaten verantwortlich. Jede Nutzung seines Kontos gilt als von ihm vorgenommen. Er muss faktur.lu unverzüglich über jede unbefugte Nutzung informieren.',

    'legal_terms_s4_title' => '4. Beschreibung des Dienstes',
    'legal_terms_s4_p' => 'faktur.lu ist eine Online-Rechnungssoftware (SaaS), die den luxemburgischen und europäischen Anforderungen entspricht und insbesondere folgendes bietet:',
    'legal_terms_s4_li1' => 'Erstellung und Verwaltung von Rechnungen, Angeboten und Gutschriften',
    'legal_terms_s4_li2' => 'Verwaltung von Kunden und Kontakten',
    'legal_terms_s4_li3' => 'FAIA-Export konform mit der AED Luxemburg',
    'legal_terms_s4_li4' => 'Zeiterfassung und Rechnungserstellung',
    'legal_terms_s4_li5' => 'Versand von Rechnungen per E-Mail',
    'legal_terms_s4_li6' => 'Dashboard und Statistiken',
    'legal_terms_s4_li7' => 'Sicherer Zugang für Buchhalter',

    'legal_terms_s5_title' => '5. Abonnements und Preise',
    'legal_terms_s5_1_title' => '5.1 Abonnementpakete',
    'legal_terms_s5_1_p' => 'Der Dienst bietet mehrere Pakete an:',
    'legal_terms_s5_plan1_title' => 'Entdeckung (Kostenlos)',
    'legal_terms_s5_plan1_desc' => 'Eingeschränkte Funktionen, ideal zum Testen des Dienstes.',
    'legal_terms_s5_plan2_title' => 'Professional',
    'legal_terms_s5_plan2_desc' => 'Vollständige Funktionen für Selbstständige und KMU. Preis wie auf der Preisseite angegeben.',
    'legal_terms_s5_2_title' => '5.2 Preise',
    'legal_terms_s5_2_p1' => 'Die Preise werden auf der Website netto (ohne MwSt.) in Euro angegeben. Die anwendbare MwSt. wird zum Zeitpunkt der Zahlung gemäß dem in Luxemburg geltenden Satz (17%) hinzugefügt.',
    'legal_terms_s5_2_p2' => 'Der Anbieter behält sich das Recht vor, seine Preise jederzeit zu ändern. Preisänderungen werden mindestens 30 Tage vor ihrem Inkrafttreten per E-Mail mitgeteilt und gelten für die nächste Abonnementverlängerung.',
    'legal_terms_s5_3_title' => '5.3 Laufzeit und Verlängerung',
    'legal_terms_s5_3_p' => 'Abonnements werden je nach Wahl des Nutzers für einen Monat oder ein Jahr abgeschlossen. Sie verlängern sich automatisch am Ende jeder Periode, sofern keine Kündigung gemäß Artikel 13 erfolgt.',
    'legal_terms_s5_4_title' => '5.4 Testphase',
    'legal_terms_s5_4_p' => 'Eine kostenlose Testphase kann angeboten werden. Nach Ablauf dieser Phase wird das Abonnement kostenpflichtig, sofern keine Kündigung erfolgt. Der Nutzer wird vor Ende der Testphase informiert.',

    'legal_terms_s6_title' => '6. Zahlung',
    'legal_terms_s6_1_title' => '6.1 Zahlungsmittel',
    'legal_terms_s6_1_p' => 'Die Zahlung erfolgt per Kreditkarte (Visa, Mastercard, American Express) über die sichere Plattform Stripe. Die Transaktionen sind verschlüsselt und entsprechen den PCI-DSS-Standards.',
    'legal_terms_s6_2_title' => '6.2 Rechnungsstellung',
    'legal_terms_s6_2_p' => 'Eine elektronische Rechnung wird ausgestellt und ist nach jeder Zahlung im Kundenbereich verfügbar. Sie kann auch auf Anfrage per E-Mail zugesandt werden.',
    'legal_terms_s6_3_title' => '6.3 Zahlungsverzug',
    'legal_terms_s6_3_p' => 'Bei Zahlungsausfall wird der Nutzer benachrichtigt und hat 7 Tage Zeit, die Zahlung zu regeln. Nach Ablauf dieser Frist wird der Zugang zu den kostenpflichtigen Funktionen ausgesetzt. Die Daten werden weitere 30 Tage aufbewahrt, bevor sie gegebenenfalls gelöscht werden.',
    'legal_terms_s6_4_title' => '6.4 MwSt.',
    'legal_terms_s6_4_p' => 'Für gewerbliche Kunden mit Sitz in einem anderen EU-Mitgliedstaat, die über eine gültige innergemeinschaftliche USt-IdNr. verfügen, wird keine MwSt. berechnet (Reverse-Charge-Verfahren). Der Kunde muss die MwSt. dann in seinem Land deklarieren.',

    'legal_terms_s7_title' => '7. Widerrufsrecht',
    'legal_terms_s7_warn_title' => 'Wichtige Information für Verbraucher',
    'legal_terms_s7_warn_p' => 'Gemäß Artikel L. 221-28 des französischen Verbrauchergesetzbuches und den gleichwertigen Bestimmungen des luxemburgischen Rechts gilt das Widerrufsrecht nicht für Verträge zur Lieferung digitaler Inhalte, die nicht auf einem körperlichen Datenträger geliefert werden, wenn die Ausführung mit ausdrücklicher vorheriger Zustimmung des Verbrauchers begonnen hat.',
    'legal_terms_s7_p1' => 'Mit dem Abschluss eines kostenpflichtigen Abonnements erkennt der Nutzer an, dass:',
    'legal_terms_s7_li1' => 'er ausdrücklich die sofortige Ausführung des Dienstes verlangt',
    'legal_terms_s7_li2' => 'er ausdrücklich auf sein 14-tägiges Widerrufsrecht verzichtet, sobald der Zugang zum kostenpflichtigen Dienst aktiviert ist',
    'legal_terms_s7_p2' => 'Für Jahresabonnements kann jedoch innerhalb der ersten 30 Tage nach Abschluss eine anteilige Rückerstattung (pro rata temporis) auf Anfrage gewährt werden, vorbehaltlich einer angemessenen Nutzung des Dienstes.',

    'legal_terms_s8_title' => '8. Pflichten des Nutzers',
    'legal_terms_s8_p' => 'Der Nutzer verpflichtet sich:',
    'legal_terms_s8_li1' => 'bei der Registrierung korrekte Angaben zu machen und diese auf dem neuesten Stand zu halten',
    'legal_terms_s8_li2' => 'den Dienst bestimmungsgemäß zu nutzen (professionelle Rechnungsstellung)',
    'legal_terms_s8_li3' => 'den Dienst nicht für rechtswidrige oder gegen die öffentliche Ordnung verstoßende Zwecke zu nutzen',
    'legal_terms_s8_li4' => 'die Vertraulichkeit seiner Zugangsdaten zu wahren',
    'legal_terms_s8_li5' => 'die für seine Tätigkeit geltende Steuer- und Buchführungsgesetzgebung einzuhalten',
    'legal_terms_s8_li6' => 'nicht zu versuchen, die Sicherheit oder den Betrieb des Dienstes zu beeinträchtigen',
    'legal_terms_s8_li7' => 'den Zugang zum Dienst nicht weiterzuverkaufen oder zu unterlizenzieren',

    'legal_terms_s9_title' => '9. Pflichten von faktur.lu',
    'legal_terms_s9_1_title' => '9.1 Verfügbarkeit des Dienstes',
    'legal_terms_s9_1_p1' => 'Der Anbieter verpflichtet sich, die erforderlichen Maßnahmen zu ergreifen, um die Verfügbarkeit des Dienstes 24/7 zu gewährleisten, mit einem Verfügbarkeitsziel von 99,5% (ohne geplante Wartungsarbeiten).',
    'legal_terms_s9_1_p2' => 'Wartungsunterbrechungen werden möglichst außerhalb der Geschäftszeiten geplant und vorher angekündigt.',
    'legal_terms_s9_2_title' => '9.2 Support',
    'legal_terms_s9_2_p_before' => 'Technischer Support ist per E-Mail verfügbar unter',
    'legal_terms_s9_2_p_after' => '. Die Reaktionszeit hängt vom Abonnementpaket ab.',
    'legal_terms_s9_3_title' => '9.3 Sicherheit und Backup',
    'legal_terms_s9_3_p' => 'Der Anbieter setzt Sicherheitsmaßnahmen ein, die den Branchenstandards entsprechen, und führt regelmäßig Datensicherungen durch.',

    'legal_terms_s10_title' => '10. Daten und Eigentum',
    'legal_terms_s10_1_title' => '10.1 Dateneigentum',
    'legal_terms_s10_1_p' => 'Der Nutzer bleibt Eigentümer aller Daten, die er in den Dienst eingibt (Rechnungen, Kundendaten usw.). Der Anbieter erwirbt keine Rechte an diesen Daten.',
    'legal_terms_s10_2_title' => '10.2 Nutzungslizenz',
    'legal_terms_s10_2_p' => 'Der Nutzer gewährt dem Anbieter eine eingeschränkte Lizenz zur Verarbeitung seiner Daten ausschließlich im Rahmen der Bereitstellung des Dienstes.',
    'legal_terms_s10_3_title' => '10.3 Datenexport',
    'legal_terms_s10_3_p' => 'Der Nutzer kann seine Daten jederzeit in Standardformaten (PDF, CSV, FAIA XML) exportieren.',
    'legal_terms_s10_4_title' => '10.4 Datenschutz',
    'legal_terms_s10_4_p_before' => 'Die Verarbeitung personenbezogener Daten unterliegt unserer',
    'legal_terms_s10_4_link' => 'Datenschutzrichtlinie',
    'legal_terms_s10_4_p_after' => '.',

    'legal_terms_s10_5_title' => '10.5 DSGVO-Auftragsverarbeitung (AVV)',
    'legal_terms_s10_5_p_before' => 'Wenn der Nutzer Verantwortlicher im Sinne der Verordnung (EU) 2016/679 (DSGVO) ist und faktur.lu personenbezogene Daten in seinem Auftrag verarbeitet, vereinbaren die Parteien, dass die ',
    'legal_terms_s10_5_link' => 'Auftragsverarbeitungsvereinbarung (AVV/DPA)',
    'legal_terms_s10_5_p_after' => ', jederzeit auf der Website abrufbar, integraler Bestandteil dieser AGB ist. Mit der Annahme der AGB akzeptiert der Nutzer auch die AVV in ihrer aktuellen Fassung. Eine separate handschriftliche Unterzeichnung kann auf Anfrage für Nutzer erfolgen, die sie für ihre eigene Compliance benötigen (insbesondere Treuhandgesellschaften und auditierten Kunden).',

    'legal_terms_s11_title' => '11. Geistiges Eigentum',
    'legal_terms_s11_p1' => 'Der Dienst, einschließlich seines Quellcodes, seiner Benutzeroberfläche, seiner Funktionen, seines Designs, seiner Marken und Logos, ist ausschließliches Eigentum des Anbieters oder seiner Partner.',
    'legal_terms_s11_p2' => 'Das Abonnement gewährt nur ein persönliches, nicht ausschließliches und nicht übertragbares Nutzungsrecht am Dienst für die Dauer des Abonnements.',

    'legal_terms_s12_title' => '12. Haftungsbeschränkung',
    'legal_terms_s12_1_title' => '12.1 Garantien',
    'legal_terms_s12_1_p' => 'Der Anbieter verpflichtet sich, den Dienst sorgfältig zu erbringen. Der Dienst wird jedoch "wie besehen" bereitgestellt und der Anbieter garantiert nicht, dass er allen spezifischen Bedürfnissen des Nutzers entspricht.',
    'legal_terms_s12_2_title' => '12.2 Beschränkung',
    'legal_terms_s12_2_p1' => 'Die Haftung des Anbieters ist auf direkte Schäden beschränkt und darf den Betrag der vom Nutzer in den letzten 12 Monaten gezahlten Beträge nicht überschreiten.',
    'legal_terms_s12_2_p2' => 'Der Anbieter haftet nicht für:',
    'legal_terms_s12_2_li1' => 'indirekte Schäden (Umsatzverlust, geschäftlicher Schaden usw.)',
    'legal_terms_s12_2_li2' => 'die Richtigkeit der vom Nutzer eingegebenen Daten',
    'legal_terms_s12_2_li3' => 'die steuerliche Konformität der vom Nutzer ausgestellten Rechnungen',
    'legal_terms_s12_2_li4' => 'Unterbrechungen aufgrund von Dritten (Hosting-Anbieter, ISP usw.)',
    'legal_terms_s12_2_li5' => 'Fälle höherer Gewalt',
    'legal_terms_s12_3_title' => '12.3 Haftung des Nutzers',
    'legal_terms_s12_3_p' => 'Der Nutzer ist allein verantwortlich für die Konformität seiner Rechnungen mit den geltenden steuerlichen Vorschriften. Der Dienst ist ein Hilfsmittel zur Rechnungsstellung, stellt jedoch keine Steuer- oder Rechtsberatung dar.',

    'legal_terms_s13_title' => '13. Kündigung',
    'legal_terms_s13_1_title' => '13.1 Kündigung durch den Nutzer',
    'legal_terms_s13_1_p1' => 'Der Nutzer kann sein Abonnement jederzeit über seinen Kundenbereich kündigen. Die Kündigung wird am Ende der laufenden Periode wirksam. Der Nutzer behält bis zu diesem Datum den Zugang zum Dienst.',
    'legal_terms_s13_1_p2' => 'Bereits gezahlte Beträge sind nicht erstattungsfähig, vorbehaltlich anderer Bestimmungen in Artikel 7.',
    'legal_terms_s13_2_title' => '13.2 Kündigung durch den Anbieter',
    'legal_terms_s13_2_p' => 'Der Anbieter kann das Abonnement kündigen bei:',
    'legal_terms_s13_2_li1' => 'Verstoß gegen diese AGB',
    'legal_terms_s13_2_li2' => 'Nicht beglichener Zahlungsausfall',
    'legal_terms_s13_2_li3' => 'Betrügerische oder missbräuchliche Nutzung des Dienstes',
    'legal_terms_s13_2_li4' => 'Einstellung des Dienstes (mit 3 Monaten Ankündigung)',
    'legal_terms_s13_3_title' => '13.3 Folgen der Kündigung',
    'legal_terms_s13_3_p' => 'Bei Kündigung hat der Nutzer 30 Tage Zeit, seine Daten zu exportieren. Nach Ablauf dieser Frist können die Daten gelöscht werden, vorbehaltlich der gesetzlichen Aufbewahrungspflichten.',

    'legal_terms_s14_title' => '14. Änderungen der AGB',
    'legal_terms_s14_p1' => 'Der Anbieter behält sich das Recht vor, diese AGB zu ändern. Änderungen werden per E-Mail und/oder durch Anzeige im Dienst mindestens 30 Tage vor ihrem Inkrafttreten mitgeteilt.',
    'legal_terms_s14_p2' => 'Die fortgesetzte Nutzung des Dienstes nach Inkrafttreten der Änderungen gilt als Annahme der neuen AGB. Bei Ablehnung kann der Nutzer sein Abonnement kündigen.',

    'legal_terms_s15_title' => '15. Anwendbares Recht und Gerichtsstand',
    'legal_terms_s15_p1' => 'Diese AGB unterliegen dem luxemburgischen Recht.',
    'legal_terms_s15_p2' => 'Im Streitfall werden sich die Parteien um eine gütliche Einigung bemühen. Andernfalls sind ausschließlich die Gerichte von Luxemburg zuständig.',
    'legal_terms_s15_p3_label' => 'Mediation:',
    'legal_terms_s15_p3_text' => 'Gemäß der europäischen Verordnung kann der Verbraucher im Falle eines ungelösten Streits kostenlos den Mediationsdienst in Anspruch nehmen. Online-Streitbeilegungsplattform:',

